    // Replays of original walkmeshes and entry scripts for the 2026-11-21 tester reports (NPC/prop
    // approach accuracy). Fixtures are generated by research/2026-11-21-tester-reports/claude-approaches/
    // make_fixtures.py from the extracted installed US assets and carry the exact event and BGI SHA256.
    internal static class ActorApproachReplayTests
    {
        private static NavigationPoint Point(JsonElement v){var a=v.EnumerateArray().Select(n=>n.GetSingle()).ToArray();return new NavigationPoint(a[0],a[1],a[2]);}
        private static NavigationPoint[] Points(JsonElement v){return v.EnumerateArray().Select(Point).ToArray();}
        private static int[] Ints(JsonElement v){return v.EnumerateArray().Select(n=>n.GetInt32()).ToArray();}
        private static string RepoFile(string relative)
        {
            var dir=new DirectoryInfo(AppContext.BaseDirectory);
            while(dir!=null && !Directory.Exists(Path.Combine(dir.FullName,"Assembly-CSharp")))dir=dir.Parent;
            if(dir==null){dir=new DirectoryInfo(Environment.CurrentDirectory);while(dir!=null && !Directory.Exists(Path.Combine(dir.FullName,"Assembly-CSharp")))dir=dir.Parent;}
            if(dir==null)throw new Exception("Repository root not found");
            return Path.Combine(dir.FullName,relative);
        }
        internal static JsonDocument Load(string fixture){return JsonDocument.Parse(File.ReadAllText(RepoFile("tests/FF9Access.Tests/Fixtures/"+fixture)));}
        // The same conversion as NativeFieldGeometry: runtime vertices (Y negated by WalkMesh.ProcessBGI),
        // PSX crossing vertices, native edge order [1,2,0], static floors, player attribute block 0x80.
        internal static FieldGeometrySnapshot Geometry(JsonElement root,float bodyRadius)
        {
            int map=root.GetProperty("Field").GetInt32();
            var triangles=root.GetProperty("Geometry").GetProperty("Triangles").EnumerateArray().Select(t=>{
                int flags=t.GetProperty("Flags").GetInt32(),normalIndex=t.GetProperty("NormalIndex").GetInt32();var normal=Point(t.GetProperty("Normal"));var neighbors=Ints(t.GetProperty("Neighbors"));
                return FieldNativeGeometryContract.CreateTriangle(t.GetProperty("Id").GetInt32(),t.GetProperty("Floor").GetInt32(),map,new FieldNativeTriangleData{
                    OriginalVertices=Points(t.GetProperty("Vertices")),CrossingVertices=Points(t.GetProperty("Crossing")),RuntimeNeighbors=neighbors,NativeNeighbors=(int[])neighbors.Clone(),EdgeClones=Ints(t.GetProperty("Clones")),
                    RuntimeFlags=flags,NativeFlags=flags,NormalIndex=normalIndex,Normal=normal,NormalInverseY=t.GetProperty("NormalInverseY").GetInt32(),Projection=FieldNativeGeometryContract.Projection(normalIndex,normal),
                    Plane=t.GetProperty("Plane").GetInt32(),ThetaX=t.GetProperty("ThetaX").GetInt32(),ThetaZ=t.GetProperty("ThetaZ").GetInt32()});
            }).ToArray();
            if(triangles.Any(t=>t==null))throw new Exception("Native triangle data rejected for field "+map);
            return new FieldGeometrySnapshot{Generation=1,Triangles=triangles,Radius=bodyRadius,AttributeMask=255,BlockedAttributes=128,Fingerprint="replay:"+map};
        }
        private static void Start(NavigationContext context,FieldGeometrySnapshot geometry,NavigationPoint start)
        {
            var support=geometry.At(start);if(support==null)throw new Exception("Start is not on the original floor: "+start);
            context.Position=start;geometry.ActiveTriangle=support.Id;
        }
        // WalkMesh.Collision (mode 4): 4*(player.talkRad+actor.talkRad)+actor.speed+60 in XZ and |dy|<400.
        // NativeFieldTargets body clearance: max(controller radius, 4*player.collRad)+4*actor.collRad.
        private static void Ranges(JsonElement root,JsonElement actor,out float body,out float collision,out float talk)
        {
            var player=root.GetProperty("Player");
            body=player.GetProperty("Size").GetInt32()*4;
            collision=Math.Max(body,4*player.GetProperty("CollRad").GetInt32())+4*actor.GetProperty("CollRad").GetInt32();
            talk=4*(player.GetProperty("TalkRad").GetInt32()+actor.GetProperty("TalkRad").GetInt32())+actor.GetProperty("Speed").GetInt32()+60;
        }
        public static void DaliWeaponShopPersonIsReachedAcrossTheCounterFromTheNativeTalkRange()
        {
            using(var json=Load("field354-shop-approach.json")) {
                var root=json.RootElement;string map="field:354:"+root.GetProperty("Scene").GetString();
                TestAssert.Equal("77868e895eefdfedcaef74f50ec87659c50019f9a92675c4ce5df5e2a9a05569",root.GetProperty("EventSha256").GetString());
                TestAssert.Equal("cd917d93568eaea10600a6bf97bbe984074abd4d4dcf6b60127aa5c10601ef9b",root.GetProperty("WalkmeshSha256").GetString());
                var person=root.GetProperty("Actors")[0];
                TestAssert.Equal(3,person.GetProperty("Sid").GetInt32());TestAssert.Equal(55,person.GetProperty("Model").GetInt32());
                TestAssert.Equal("64fada6b79b89cdb528cf11c4f8158cbc892eb05c863bcd6991974b9c97ced55",person.GetProperty("EntrySha256").GetString());
                TestAssert.True(person.GetProperty("Talk").GetBoolean());
                var position=Point(person.GetProperty("Position"));
                TestAssert.Equal(new NavigationPoint(-226,211,-241),position);
                float body,collision,talk;Ranges(root,person,out body,out collision,out talk);
                TestAssert.Near(80,body,0);TestAssert.Near(152,collision,0);TestAssert.Near(398,talk,0);
                var geometry=Geometry(root,body);
                // The person stands on native floor behind the counter (triangles 12-19) which shares no edge with the shop floor.
                var island=geometry.At(new NavigationPoint(-300,61,-200));TestAssert.True(island!=null);
                var planner=new FieldRoutePlanner();
                foreach(var start in Points(root.GetProperty("Player").GetProperty("Starts"))) {
                    var context=TestFixtures.Context(map);Start(context,geometry,start);
                    var target=new NavigationTarget{Id=new TargetIdentity(TargetKind.FieldActor,map,3),Generation=1,Category=NavigationCategory.People,IsInteractive=true,Position=position};
                    target.ApproachCandidates=FieldActorApproaches.Create(context.Position,position,collision,talk);
                    var route=planner.Plan(context,target,geometry);
                    if(!route.Success)throw new Exception("Weapon shop person unreachable from "+start+": "+route.Failure);
                    float distance=FieldGeometrySnapshot.Horizontal(route.ApproachPoint,position);
                    TestAssert.True(distance>collision && distance<talk);
                    TestAssert.True(Math.Abs(route.ApproachPoint.Y-position.Y)<400);
                    var support=geometry.At(route.ApproachPoint);
                    TestAssert.True(support!=null && support.Id!=island.Id && route.ApproachPoint.X>=42);
                    var from=context.Position;foreach(var point in route.Waypoints){TestAssert.True(geometry.IsSegmentClear(from,point));from=point;}
                    TestAssert.True(FieldGeometrySnapshot.Horizontal(from,route.ApproachPoint)<0.01f);
                    // Another floor: beyond the native vertical talk interval there is no approach at all.
                    target.Position=new NavigationPoint(position.X,position.Y+400,position.Z);
                    target.ApproachCandidates=FieldActorApproaches.Create(context.Position,target.Position,collision,talk);
                    TestAssert.Equal(RouteFailure.TargetOutsideMesh,planner.Plan(context,target,geometry).Failure);
                    // A talk range that ends before the shop floor keeps the honest disconnection.
                    target.Position=position;
                    target.ApproachCandidates=FieldActorApproaches.Create(context.Position,position,collision,300);
                    TestAssert.Equal(RouteFailure.Disconnected,planner.Plan(context,target,geometry).Failure);
                }
            }
        }
        private static ScriptInstruction[] Instructions(JsonElement values)
        {
            return values.EnumerateArray().Select(v=>{var item=new ScriptInstruction(v.GetProperty("Offset").GetInt32(),v.GetProperty("NextOffset").GetInt32(),v.GetProperty("Opcode").GetInt32()) {
                Arguments=v.GetProperty("Arguments").EnumerateArray().Select(a=>a.ValueKind==JsonValueKind.Null?(int?)null:a.GetInt32()).ToArray(),
                ArgumentExpressions=v.GetProperty("ArgumentExpressions").EnumerateArray().Select(a=>a.ValueKind==JsonValueKind.Null?null:a.EnumerateArray().Select(b=>b.GetByte()).ToArray()).ToArray()
            };item.Argument=item.Constant(0);item.Expression=item.ArgumentExpression(0);return item;}).ToArray();
        }
        private const string AirshipHash="97a7d5b011b1919f643ff64c3c71051dac3e546e86c71efdd14a575784d91a6c",ExamineRegionHash="5cb07de3fe0d7f1e1f295be008236fc9afc0963887a0a429da916a4d718ce6fa";
        // EBin opcode values: REQ 0x10, TURNA 0x51, FICON 0x68.
        private static readonly FieldInteractionOpcodes Ops=new FieldInteractionOpcodes{IconOpcode=0x68};
        public static void ObservatoryModelAirshipIsExaminedFromItsNativeRegion()
        {
            using(var json=Load("field457-observatory-airship.json")) {
                var root=json.RootElement;string map="field:457:"+root.GetProperty("Scene").GetString();
                TestAssert.Equal("25398de8f32862d2912d6677b1bc4b271167dbc91e4c68a6117fd88cb5c21558",root.GetProperty("EventSha256").GetString());
                TestAssert.Equal("346342dd1fda219d5168ac28fff802314388e1d5f2fbcfad933ea139e032a745",root.GetProperty("WalkmeshSha256").GetString());
                var airship=root.GetProperty("Actors")[0];
                TestAssert.Equal(10,airship.GetProperty("Sid").GetInt32());TestAssert.Equal(23,airship.GetProperty("Model").GetInt32());TestAssert.Equal(AirshipHash,airship.GetProperty("EntrySha256").GetString());
                TestAssert.False(airship.GetProperty("Talk").GetBoolean());TestAssert.False(airship.GetProperty("Push").GetBoolean());
                var position=Point(airship.GetProperty("Position"));TestAssert.Equal(new NavigationPoint(-747,470,505),position);
                TestAssert.Equal("Airship",FieldVisibleLabels.Read(23));
                var region=root.GetProperty("Regions")[0];
                TestAssert.Equal(11,region.GetProperty("Sid").GetInt32());TestAssert.Equal(ExamineRegionHash,region.GetProperty("EntrySha256").GetString());
                var polygon=Points(region.GetProperty("Polygon"));
                // Native ownership: the region's Confirm handler requests the controlled player's function 19
                // (REQ 6 250 19) and that function first turns the player toward object 10 (TURNA 10).
                var confirm=Instructions(root.GetProperty("Functions").GetProperty("11.3"));
                if(!confirm.Any(i=>i.Opcode==0x10 && i.Constant(0)==6 && i.Constant(1)==250 && i.Constant(2)==19))throw new Exception("Region 11 Confirm handler does not request the player function 19: "+string.Join(" ",confirm.Select(i=>i.Opcode+"("+string.Join(",",(i.Arguments??new int?[0]).Select(a=>a.HasValue?a.Value.ToString():"e"))+")")));
                var examine=Instructions(root.GetProperty("Functions").GetProperty("14.19"));
                TestAssert.Equal(0x51,examine[0].Opcode);TestAssert.Equal(10,examine[0].Constant(0).Value);
                var binding=FieldInteractionBindings.FindActor(457,10,AirshipHash,23,10);
                if(binding==null)throw new Exception("No PlayerExamines binding row for the model airship");TestAssert.Equal(11,binding.RegionSid);TestAssert.Equal(ExamineRegionHash,binding.RegionHash);
                TestAssert.Equal(FieldInteractionEvidence.PlayerExamines,binding.Evidence);TestAssert.Equal(19,binding.RequestedTag);TestAssert.Equal(6,binding.RequestedLevel);
                TestAssert.True(FieldInteractionBindings.RequestedObjectIsPlayer(binding));
                TestAssert.True(FieldInteractionBindings.FindRegion(457,11,ExamineRegionHash)==binding);
                // The other examine spot (region 12) turns toward a fixed point, not this model: it stays unbound.
                TestAssert.True(FieldInteractionBindings.FindRegion(457,12,root.GetProperty("Regions")[1].GetProperty("EntrySha256").GetString())==null);
                // Presence from the hanging model's position; closed when the region is absent, the player is busy or the guard proves unavailable.
                if(!FieldInteractionBindings.WithinReach(binding,position,polygon))throw new Exception("Model airship not within reach of its examine region");
                TestAssert.False(FieldInteractionBindings.WithinReach(binding,new NavigationPoint(-1500,470,505),polygon));
                Func<FieldInteractionPresence> live=()=>new FieldInteractionPresence{ActorRendered=true,ActorObserved=true,ActorLevel=7,LiveRegions=1,RegionLevel=7,RegionTalkable=true,MapTalkPermitted=true,RegionGuard=FieldInteractionState.Unknown,ActorPosition=position,Region=polygon};
                if(!FieldInteractionBindings.Present(binding,live()))throw new Exception("Binding not present with the live observatory facts");
                var absent=live();absent.LiveRegions=0;TestAssert.False(FieldInteractionBindings.Present(binding,absent));
                var busy=live();busy.ActorLevel=6;TestAssert.False(FieldInteractionBindings.Present(binding,busy));
                var closed=live();closed.RegionGuard=FieldInteractionState.Unavailable;TestAssert.False(FieldInteractionBindings.Present(binding,closed));
                var hidden=live();hidden.ActorRendered=false;TestAssert.False(FieldInteractionBindings.Present(binding,hidden));
                var geometry=Geometry(root,root.GetProperty("Player").GetProperty("Size").GetInt32()*4);
                var planner=new FieldRoutePlanner();
                foreach(var start in Points(root.GetProperty("Player").GetProperty("Starts"))) {
                    var context=TestFixtures.Context(map);Start(context,geometry,start);
                    // Before the binding the model was scenery: its viewing point lies outside the examine region (the reported stop).
                    var viewing=new NavigationTarget{Id=new TargetIdentity(TargetKind.FieldActor,map,10),Generation=1,Category=NavigationCategory.Objects,IsInteractive=false,UseViewingPoint=true,Position=position,ApproachCandidates=new[]{position}};
                    var look=planner.Plan(context,viewing,geometry);
                    if(!look.Success)throw new Exception("Viewing route failed from "+start+": "+look.Failure);
                    if(FieldRegionApproaches.CanStopInside(polygon,look.ApproachPoint,0))throw new Exception("Viewing point already inside the examine region: "+look.ApproachPoint);
                    // Bound: the examine region, inset by the follower's arrival radius, is the approach and the route reaches it on connected floor.
                    float arrival=FieldAnalogMovement.ArrivalRadius(geometry.Radius,1);
                    var planned=FieldInteractionBindings.StoppingRegion(polygon,arrival+.5f);
                    TestAssert.True(planned!=polygon && planned.Length==4);
                    var bound=new NavigationTarget{Id=new TargetIdentity(TargetKind.FieldActor,map,10),Generation=1,Category=NavigationCategory.Objects,IsInteractive=true,Position=position,InteractionUid=11,InteractionRegion=planned,ApproachCandidates=new[]{position}};
                    var route=planner.Plan(context,bound,geometry);
                    if(!route.Success)throw new Exception("Model airship examine region unreachable from "+start+": "+route.Failure);
                    if(!FieldRegionApproaches.CanStopInside(polygon,route.ApproachPoint,arrival)) {
                        var a=route.ApproachPoint;var edges=new List<string>();
                        for(int i=0;i<polygon.Length;i++){var p1=polygon[i];var p2=polygon[(i+1)%polygon.Length];float dx=p2.X-p1.X,dz=p2.Z-p1.Z;float cross=(dx*(a.Z-p1.Z)-dz*(a.X-p1.X))/(float)Math.Sqrt(dx*dx+dz*dz);edges.Add(cross.ToString("0.0"));}
                        throw new Exception("Bound approach outside the examine region margin: ("+a.X+","+a.Y+","+a.Z+") edge distances "+string.Join(" ",edges)+" inside0="+FieldRegionApproaches.CanStopInside(polygon,a,0));
                    }
                    TestAssert.True(geometry.IsSegmentClear(route.ApproachPoint,route.ApproachPoint));
                    var from=context.Position;foreach(var point in route.Waypoints){TestAssert.True(geometry.IsSegmentClear(from,point));from=point;}
                    TestAssert.True(FieldGeometrySnapshot.Horizontal(from,route.ApproachPoint)<0.01f);
                }
            }
        }
        public static void ObservatoryAirshipBubbleAsksForATurnOnlyWhenHeadingIsTheMissingStep()
        {
            using(var json=Load("field457-observatory-airship.json")) {
                var bubble=Instructions(json.RootElement.GetProperty("Functions").GetProperty("11.2"));
                TestAssert.True(bubble.Any(i=>i.Opcode==0x68 && i.Constant(0)==1));
                Func<bool,byte,ScriptSnapshot> state=(control,busyFlag)=>{var map=new byte[1024];map[38]=busyFlag;return new ScriptSnapshot(new byte[2048],map,new byte[64]){UserControl=control};};
                // Heading 60 is inside the native window 21..97: the bubble is offered now.
                var facing=FieldInteractionGuard.FacingGate(bubble,state(true,0),Ops,14,60);
                TestAssert.True(facing.OfferedNow);
                // Heading 150 is outside it: turning alone offers the bubble.
                var turned=FieldInteractionGuard.FacingGate(bubble,state(true,0),Ops,14,150);
                TestAssert.False(turned.OfferedNow);TestAssert.True(turned.OfferedByTurning);
                // While the other examine scene runs (M4[38]) no heading offers it; nothing is claimed.
                var closed=FieldInteractionGuard.FacingGate(bubble,state(true,1),Ops,14,60);
                TestAssert.False(closed.OfferedNow);TestAssert.False(closed.OfferedByTurning);
                // Without user control the handler returns before the guard.
                var scripted=FieldInteractionGuard.FacingGate(bubble,state(false,0),Ops,14,60);
                TestAssert.False(scripted.OfferedNow);TestAssert.False(scripted.OfferedByTurning);
                // An unreadable handler claims nothing either.
                var unknown=FieldInteractionGuard.FacingGate(new ScriptInstruction[0],state(true,0),Ops,14,60);
                TestAssert.False(unknown.OfferedNow || unknown.OfferedByTurning);
                // Bound readiness: a missing turn keeps Talkable without FacingWithinArc (TurnNeeded); facing needs the shown bubble.
                var turn=FieldInteractionBindings.Readiness(true,true,true,false,false);
                TestAssert.True(turn.Talkable && !turn.FacingWithinArc && turn.InRange);
                TestAssert.False(FieldInteractionBindings.Readiness(true,true,true,true,false).Talkable);
                TestAssert.True(FieldInteractionBindings.Readiness(true,true,true,true,true).FacingWithinArc);
            }
        }
        public static void StoppingRegionInsetsConvexRegionsAndKeepsThinOrConcaveOnes()
        {
            NavigationPoint P(float x,float z){return new NavigationPoint(x,0,z);}
            var square=new[]{P(0,0),P(100,0),P(100,100),P(0,100)};
            var inset=FieldInteractionBindings.StoppingRegion(square,10);
            TestAssert.Equal(4,inset.Length);
            foreach(var corner in new[]{P(10,10),P(90,10),P(90,90),P(10,90)})TestAssert.True(inset.Any(v=>NavigationPoint.Distance(v,corner)<0.01f));
            // Either winding is inset toward the interior.
            var reversed=FieldInteractionBindings.StoppingRegion(new[]{P(0,0),P(0,100),P(100,100),P(100,0)},10);
            foreach(var corner in new[]{P(10,10),P(90,10),P(90,90),P(10,90)})TestAssert.True(reversed.Any(v=>NavigationPoint.Distance(v,corner)<0.01f));
            // The observatory examine strip keeps a usable interior at the follower's margin.
            var strip=new[]{P(-550,282),P(-573,193),P(-350,-150),P(-360,184)};
            var planned=FieldInteractionBindings.StoppingRegion(strip,4.5f);
            TestAssert.True(planned!=strip);
            foreach(var vertex in planned)TestAssert.True(FieldRegionApproaches.CanStopInside(strip,vertex,4.4f));
            // Too thin for the margin, concave, degenerate or invalid input: the native polygon stays.
            TestAssert.True(ReferenceEquals(square,FieldInteractionBindings.StoppingRegion(square,60)));
            var concave=new[]{P(0,0),P(100,0),P(100,100),P(50,20),P(0,100)};
            TestAssert.True(ReferenceEquals(concave,FieldInteractionBindings.StoppingRegion(concave,5)));
            TestAssert.True(ReferenceEquals(square,FieldInteractionBindings.StoppingRegion(square,0)));
            TestAssert.True(ReferenceEquals(square,FieldInteractionBindings.StoppingRegion(square,float.NaN)));
            var flat=new[]{P(0,0),P(50,0),P(100,0)};
            TestAssert.True(ReferenceEquals(flat,FieldInteractionBindings.StoppingRegion(flat,5)));
            TestAssert.True(FieldInteractionBindings.StoppingRegion(null,5)==null);
        }
        private static FieldGeometrySnapshot TwoFloors()
        {
            // Shop floor x in [0,1000]; a separate strip x in [-600,-100] shares no edge with it.
            NavigationPoint P(float x,float z){return new NavigationPoint(x,0,z);}
            return new FieldGeometrySnapshot{Generation=1,Radius=40,ActiveTriangle=0,AttributeMask=255,Triangles=new[]{
                new FieldTriangle{Id=0,Vertices=new[]{P(0,0),P(1000,0),P(0,1000)},Neighbors=new[]{-1,1,-1}},
                new FieldTriangle{Id=1,Vertices=new[]{P(1000,0),P(1000,1000),P(0,1000)},Neighbors=new[]{-1,-1,0}},
                new FieldTriangle{Id=2,Vertices=new[]{P(-600,0),P(-100,0),P(-600,1000)},Neighbors=new[]{-1,3,-1}},
                new FieldTriangle{Id=3,Vertices=new[]{P(-100,0),P(-100,1000),P(-600,1000)},Neighbors=new[]{-1,-1,2}}}};
        }
        public static void CollisionRingIsKeptWhenItHasFloorConnectedWithThePlayer()
        {
            var geometry=TwoFloors();var player=new NavigationPoint(100,0,100);var actor=new NavigationPoint(500,0,500);
            var points=FieldActorApproaches.OnSurfaces(FieldActorApproaches.Create(player,actor,100,400),actor,geometry);
            TestAssert.True(points.Length>0);
            foreach(var point in points)TestAssert.Near(104,FieldGeometrySnapshot.Horizontal(point,actor),0.01f);
        }
        public static void TalkRingIsUsedOnlyWhenTheCollisionRingHasNoConnectedFloor()
        {
            var geometry=TwoFloors();var player=new NavigationPoint(100,0,100);var actor=new NavigationPoint(-300,0,500);
            var points=FieldActorApproaches.OnSurfaces(FieldActorApproaches.Create(player,actor,100,400),actor,geometry);
            TestAssert.True(points.Length>0);
            foreach(var point in points){TestAssert.True(point.X>=0);TestAssert.Near(360,FieldGeometrySnapshot.Horizontal(point,actor),0.01f);}
            var context=TestFixtures.Context();context.Position=player;
            var target=new NavigationTarget{Id=new TargetIdentity(TargetKind.FieldActor,context.LogicalMapKey,5),Generation=1,IsInteractive=true,Position=actor,ApproachCandidates=FieldActorApproaches.Create(player,actor,100,400)};
            var route=new FieldRoutePlanner().Plan(context,target,geometry);
            TestAssert.True(route.Success);TestAssert.True(route.ApproachPoint.X>=0);
        }
        public static void UnconnectedRingsKeepTheHonestPlannerFailure()
        {
            var geometry=TwoFloors();var player=new NavigationPoint(100,0,100);var actor=new NavigationPoint(-300,0,500);
            var candidates=FieldActorApproaches.Create(player,actor,100,300);
            var points=FieldActorApproaches.OnSurfaces(candidates,actor,geometry);
            TestAssert.True(points.Length>0);foreach(var point in points)TestAssert.True(point.X<0);
            var context=TestFixtures.Context();context.Position=player;
            var target=new NavigationTarget{Id=new TargetIdentity(TargetKind.FieldActor,context.LogicalMapKey,5),Generation=1,IsInteractive=true,Position=actor,ApproachCandidates=candidates};
            TestAssert.Equal(RouteFailure.Disconnected,new FieldRoutePlanner().Plan(context,target,geometry).Failure);
            // Without a known player support every supported ring is offered, nearest first as before.
            geometry.ActiveTriangle=-1;
            points=FieldActorApproaches.OnSurfaces(FieldActorApproaches.Create(player,actor,100,400),actor,geometry);
            foreach(var point in points)TestAssert.Near(104,FieldGeometrySnapshot.Horizontal(point,actor),0.01f);
        }
    }
